options.customCss:
/* Receipt-to-Ledger form theme: a paper receipt on a dark green desk.
   Applied to every n8n form page (upload, review, logged, not logged) via the node's Custom CSS option.
   Lucy: the tokens at the top are the quick knobs. */
:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", Roboto, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --ink: #17221c;
  --ink-soft: #55635b;
  --paper: #f7f4ec;
  --paper-edge: #e3ddcc;
  --green: #1d8653;
  --green-soft: #e3f3e9;
  --amber: #a5620a;
  --amber-soft: #fbf0dc;

  --font-size-header: 24px;
  --font-size-label: 14px;
  --font-size-input: 15px;
  --font-size-paragraph: 15px;
  --color-background: #0f1412;
  --color-card-bg: var(--paper);
  --color-card-border: var(--paper-edge);
  --color-card-shadow: rgba(0, 0, 0, 0.45);
  --color-header: var(--ink);
  --color-header-subtext: var(--ink-soft);
  --color-label: var(--ink);
  --color-link: var(--ink-soft);
  --color-input-border: #d6cfbd;
  --color-input-text: var(--ink);
  --color-input-bg: #fffdf8;
  --color-focus-border: var(--green);
  --color-submit-btn-bg: var(--green);
  --color-submit-btn-text: #ffffff;
  --color-required: var(--green);
  --color-html-text: var(--ink);
  --color-html-link: var(--green);
  --border-radius-card: 14px;
  --border-radius-input: 10px;
  --container-width: 460px;
  --padding-container-top: 40px;
  --padding-card: 28px;
  --box-shadow-card: 0 24px 60px rgba(0, 0, 0, 0.45);
}

body {
  min-height: 100vh;
  background: radial-gradient(900px 420px at 50% -8%, #21402f 0%, #0f1412 62%) fixed, #0f1412;
  padding: 0 16px 48px;
}

/* The card is the receipt: brand line on top, torn edge at the bottom. */
.card {
  position: relative;
  border-radius: var(--border-radius-card) var(--border-radius-card) 0 0;
  border-top: 5px solid var(--green);
  margin-bottom: 28px;
}
.card::after {
  content: "";
  position: absolute;
  left: -1px;
  right: -1px;
  bottom: -12px;
  height: 12px;
  background:
    linear-gradient(135deg, var(--paper) 50%, transparent 50%) 0 0 / 16px 12px repeat-x,
    linear-gradient(-135deg, var(--paper) 50%, transparent 50%) 0 0 / 16px 12px repeat-x;
}
.form-header::before {
  content: "RECEIPT-TO-LEDGER";
  display: block;
  font: 600 11px/1 var(--mono);
  letter-spacing: 0.18em;
  color: var(--green);
  margin-bottom: 12px;
}
.form-header h1 {
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.form-header p {
  color: var(--ink-soft);
  line-height: 1.5;
}

.form-label { font-weight: 600; }
input[type="radio"], input[type="checkbox"] { accent-color: var(--green); }
input, select, textarea { transition: border-color 0.15s, box-shadow 0.15s; }
input:focus, select:focus, textarea:focus { box-shadow: 0 0 0 3px rgba(29, 134, 83, 0.18); }

#submit-btn {
  font-size: 16px;
  font-weight: 650;
  letter-spacing: 0.01em;
  border-radius: 12px;
  box-shadow: 0 6px 16px rgba(29, 134, 83, 0.35);
  transition: transform 0.08s, filter 0.15s;
}
#submit-btn:hover { filter: brightness(1.08); }
#submit-btn:active { transform: translateY(1px); }

/* Review page: what the AI read, printed like a receipt.
   n8n strips class attributes from custom HTML, so these style plain tags inside the HTML block. */
.form-group.html {
  font-family: var(--mono);
  background: #fffdf8;
  border: 1px solid var(--paper-edge);
  border-radius: 10px;
  padding: 16px 18px;
  color: var(--ink);
  text-align: left;
}
.form-group.html h3 { font: 700 16px/1.3 var(--mono); letter-spacing: 0.02em; margin: 0; }
.form-group.html > div > p, .form-group.html p { margin: 4px 0 0; font-size: 13px; color: var(--ink-soft); }
.card table { width: 100%; border-collapse: collapse; margin: 12px 0 4px; border-top: 1px dashed #cfc7b2; border-bottom: 1px dashed #cfc7b2; }
.card td, .card th { padding: 4px 0; font: 14px/1.4 var(--mono); color: var(--ink); text-align: left; }
.card td:last-child, .card th:last-child { text-align: right; }
.card th { font-weight: 700; font-size: 16px; padding-top: 8px; border-top: 1px solid #e6e0d0; }
.form-group.html small, .card small {
  display: inline-block; margin: 8px 6px 0 0;
  font: 500 12px/1 var(--font-family); color: var(--ink);
  background: #efeadd; border-radius: 999px; padding: 6px 10px;
}
.form-group.html strong, .form-group.html em, .form-group.html i {
  display: block; margin-top: 10px; border-radius: 8px; padding: 9px 12px;
  font: 600 13px/1.4 var(--font-family); font-style: normal;
}
.form-group.html strong { background: var(--green-soft); color: var(--green); }
.form-group.html em { background: var(--amber-soft); color: var(--amber); }
.form-group.html i { background: #eef0ea; color: var(--ink-soft); font-weight: 500; margin-top: 6px; }

/* Decision as big tap targets instead of tiny checkboxes. */
.multiselect { display: grid; gap: 8px; }
.multiselect-option {
  display: flex; align-items: center; gap: 10px;
  border: 1px solid var(--color-input-border); border-radius: 10px;
  background: var(--color-input-bg); padding: 11px 12px; margin: 0;
}
.multiselect-option:has(:checked) { border-color: var(--green); background: var(--green-soft); }
.multiselect-option label { font-size: 15px; color: var(--ink); cursor: pointer; flex: 1; }

/* Logged page: the budget at a glance. */
.card h4 {
  margin: 18px 0 0; font: 600 11px/1 var(--mono); letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--ink-soft);
}
.card progress {
  -webkit-appearance: none; appearance: none; display: block;
  width: 100%; height: 12px; margin: 10px 0 0; border: 0; border-radius: 999px;
  overflow: hidden; background: #e6e0d0;
}
.card progress::-webkit-progress-bar { background: #e6e0d0; border-radius: 999px; }
.card progress::-webkit-progress-value { background: var(--green); border-radius: 999px; }
.card progress::-moz-progress-bar { background: var(--green); border-radius: 999px; }
.card progress + table { border: 0; margin-top: 6px; }
.card progress + table td { font-weight: 600; }
.card blockquote, .card aside {
  margin: 12px 0 0; border-radius: 8px; padding: 10px 12px;
  font-size: 14px; line-height: 1.4; text-align: left;
}
.card blockquote { background: #e8eefb; color: #23407a; }
.card aside { background: var(--amber-soft); color: var(--amber); }

/* Completion pages put the message in .header p; keep the table readable there. */
.card .header table { margin-top: 10px; }
.card .header th:first-child { font-size: 12px; letter-spacing: -1px; color: var(--green); font-weight: 400; }
.card .header td:first-child { color: var(--ink-soft); padding-right: 12px; }

/* Never wider than the screen; keep the inner padding on narrow screens too. */
.container, section, .card { max-width: 100%; }
.card { padding: var(--padding-card) !important; }
.form-group.html { margin-bottom: 18px; }
.multiselect, .multiselect-option { margin-left: 0 !important; }

@media (max-width: 480px) {
  :root { --padding-card: 20px; --padding-container-top: 20px; }
}

/* ---- Lucy pass 2 (2026-11-15) ---- */
/* Even rhythm between fields on every page. */
.inputs-wrapper > div, .inputs-wrapper > .form-group { margin-bottom: 22px !important; }
.inputs-wrapper > div:last-child { margin-bottom: 8px !important; }
.form-label { display: block; margin-bottom: 8px; }

/* Review card: printed straight onto the receipt instead of a box inside a box. */
.form-group.html {
  background: transparent; border: 0; border-radius: 0;
  border-top: 1px dashed #cfc7b2; border-bottom: 1px dashed #cfc7b2;
  padding: 18px 0 16px; text-align: center;
}
.form-group.html h3 { font-size: 18px; letter-spacing: 0.08em; text-transform: uppercase; }
.form-group.html table { border-top: 0; margin-top: 14px; }
.form-group.html td { color: var(--ink-soft); }
.form-group.html th { font-size: 17px; border-top: 1px dashed #cfc7b2; padding-top: 10px; }
.form-group.html small { margin: 10px 3px 0; background: #ebe5d5; font-weight: 600; }
.form-group.html strong, .form-group.html em, .form-group.html i { text-align: left; margin-top: 12px; }
.form-group.html p:has(> small) { margin-top: 2px; }

/* Decision: full-width rows, flush with the other fields, bigger target. */
.multiselect { gap: 10px; margin: 0 !important; }
.multiselect-option {
  min-height: 52px; padding: 0 14px; gap: 12px; margin: 0 !important;
  transition: border-color .15s, background .15s; cursor: pointer;
}
.multiselect-option:hover { border-color: #b9b09a; }
.multiselect-option label { padding: 15px 0; margin: 0; font-weight: 500; }
.multiselect-option:has(:checked) label { font-weight: 650; color: var(--green); }
.multiselect-checkbox { flex: none; margin: 0 !important; position: static !important; }

/* Logged / Not logged pages share the header treatment of the form pages. */
.card .header::before {
  content: "RECEIPT-TO-LEDGER"; display: block; font: 600 11px/1 var(--mono);
  letter-spacing: 0.18em; color: var(--green); margin-bottom: 12px;
}
.card .header h1 { font-weight: 700; font-size: 26px; letter-spacing: -0.01em; color: var(--ink); margin-bottom: 6px; }
.card .header p { color: var(--ink-soft); font-size: 15px; line-height: 1.5; }
.card .header p > b { display: block; font: 700 15px/1.3 var(--mono); letter-spacing: 0.08em; color: var(--ink); margin-top: 6px; }
.card .header h4 { margin-top: 22px; padding-bottom: 10px; border-bottom: 1px dashed #cfc7b2; }
.card .header table { border: 0; margin-top: 4px; }
/* Budget bar: <s> holds 20 block characters; the filled part sits in <mark>. */
.card .header s {
  display: block; height: 12px; overflow: hidden; border-radius: 999px; margin: 14px 0 6px;
  font: 22px/12px var(--mono); letter-spacing: -0.5px; white-space: nowrap; text-decoration: none;
  color: #e1dac8; text-align: left;
}
.card .header s mark { background: none; color: var(--green); }
.card .header td { padding: 8px 0; border-bottom: 1px dotted #e1dac8; vertical-align: top; }
.card .header td:first-child { font-size: 13px; padding-right: 16px; }
.card .header td:last-child { white-space: nowrap; }
.card .header td:last-child { font-weight: 600; }
.card .header tr:last-child td { border-bottom: 0; }

/* n8n pads the radio list 6px; line it up with the other fields. */
.multiselect { padding: 0 !important; }
.multiselect-option { padding-top: 0; }
.multiselect[data-radio-select] .multiselect-checkbox { width: 20px; height: 20px; border-width: 1.5px; border-color: #b9b09a; }
.multiselect[data-radio-select] .multiselect-checkbox:checked { border-width: 6px; border-color: var(--green); background: #fff; }

/* Only show the category picker once "Change category" is picked. */
.inputs-wrapper:has(.multiselect[data-radio-select]):not(:has(.multiselect-option:nth-child(2) :checked)) .form-group:has(select) { display: none; }
.form-group:has(select) { animation: r2l-in .18s ease-out; }
@keyframes r2l-in { from { opacity: 0; transform: translateY(-4px); } }

/* n8n reserves a blank line under every field for its "required" error; only take the space when it shows. */
.error-hidden:not(.error-show) { display: none; }

/* Decision: one row of three instead of a stack. */
.multiselect[data-radio-select] { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; }
.multiselect[data-radio-select] .multiselect-option { position: relative; min-height: 0; padding: 0; justify-content: center; text-align: center; }
.multiselect[data-radio-select] .multiselect-checkbox { position: absolute !important; opacity: 0; pointer-events: none; }
.multiselect[data-radio-select] .multiselect-option label { padding: 14px 6px; font-size: 14px; font-weight: 600; line-height: 1.2; color: var(--ink); }
.multiselect[data-radio-select] .multiselect-option:has(:focus-visible) { outline: 2px solid var(--green); outline-offset: 2px; }
.multiselect[data-radio-select] .multiselect-option:nth-child(3):has(:checked) { border-color: #b4532a; background: #fbe9e2; }
.multiselect[data-radio-select] .multiselect-option:nth-child(3):has(:checked) label { color: #9a3f1b; }
.multiselect[data-radio-select] .multiselect-option label { text-align: center !important; }
.multiselect[data-radio-select] .multiselect-option:has(:checked) label { color: var(--green); }
.multiselect[data-radio-select] .multiselect-option:nth-child(3):has(:checked) label { color: #9a3f1b; }
/* A: icon tiles */
.multiselect[data-radio-select] .multiselect-option label::before { display: block; font-size: 20px; margin-bottom: 4px; font-weight: 700; }
.multiselect[data-radio-select] .multiselect-option:nth-child(1) label::before { content: "✓"; }
.multiselect[data-radio-select] .multiselect-option:nth-child(2) label::before { content: "✎"; }
.multiselect[data-radio-select] .multiselect-option:nth-child(3) label::before { content: "✕"; }
.multiselect[data-radio-select] .multiselect-option label { padding: 12px 6px 13px; }

parameters.jsCode:
// Keep the uploaded file under a fixed name, whatever the form field is called.
const item = $input.first();
const keys = Object.keys(item.binary || {});
if (!keys.length) throw new Error('No receipt photo was uploaded');
return [{ json: item.json, binary: { receipt: item.binary[keys[0]] } }];

parameters.text:
You are a bookkeeper for a university student in British Columbia, Canada. Read this receipt and reply with ONLY a JSON object, no prose, no code fences:
{"vendor": string, "date": "YYYY-MM-DD", "subtotal": number, "gst": number, "pst": number, "hst": number, "total": number, "currency": "CAD" or other ISO code, "category": one of ["Groceries", "Dining & coffee", "Transport", "Textbooks & school", "Rent & utilities", "Subscriptions", "Health", "Entertainment", "Shopping", "Other"], "confidence": number 0-1, "notes": string}
Rules: use 0 for a tax that is not printed. GST is 5% federal; BC PST is 7%. Basic groceries are usually tax-free and restaurant meals are usually GST-only. Never invent numbers: if a value is unreadable use null and say so in notes. Pick the closest category.

parameters.jsCode:
const CATS_ = ["Groceries", "Dining & coffee", "Transport", "Textbooks & school", "Rent & utilities", "Subscriptions", "Health", "Entertainment", "Shopping", "Other"];
// Turn the model's reply into clean numbers and run the bookkeeping checks.
const r = $input.first().json;
const raw = String(r.content ?? r.text ?? r.message?.content ?? r.output ?? JSON.stringify(r));
const m = raw.replace(/```(json)?/g, '').match(/\{[\s\S]*\}/);
if (!m) throw new Error('The model did not return JSON: ' + raw.slice(0, 200));
const d = JSON.parse(m[0]);
const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Math.round(Number(v) * 100) / 100;
const out = {
  vendor: d.vendor || 'Unknown vendor',
  date: /^\d{4}-\d{2}-\d{2}$/.test(d.date || '') ? d.date : new Date().toISOString().slice(0, 10),
  subtotal: num(d.subtotal), gst: num(d.gst) ?? 0, pst: num(d.pst) ?? 0, hst: num(d.hst) ?? 0,
  total: num(d.total), currency: d.currency || 'CAD',
  category: CATS_.includes(d.category) ? d.category : 'Other',
  confidence: num(d.confidence) ?? 0, notes: d.notes || '',
  paid_with: $('Upload receipt').first().json['Paid with'] || '',
};
// Roommate split: equal shares between you and everyone named.
const names = String($('Upload receipt').first().json['Split with'] || '').split(/[,&]| and /).map(s => s.trim()).filter(Boolean);
out.split_with = names.join(', ');
const t = out.total ?? 0;
out.each_owes = names.length ? Math.round(t / (names.length + 1) * 100) / 100 : 0;
out.your_share = Math.round((t - out.each_owes * names.length) * 100) / 100;
out.split_text = names.length ? `Split ${names.length + 1} ways: ${names.join(', ')} each owe you $${out.each_owes.toFixed(2)}; your share $${out.your_share.toFixed(2)}` : 'Not split';
const flags = [], info = [];
if (out.total === null) flags.push('Total could not be read');
if (out.subtotal !== null && out.total !== null) {
  const sum = out.subtotal + out.gst + out.pst + out.hst;
  if (Math.abs(sum - out.total) > 0.05) flags.push(`Subtotal + taxes = $${sum.toFixed(2)}, but total says $${out.total.toFixed(2)}`);
  if (out.gst > out.subtotal * 0.05 + 0.06) flags.push('GST is more than 5% of the subtotal');
  if (out.pst > out.subtotal * 0.07 + 0.06) flags.push('PST is more than 7% of the subtotal');
  if ((out.gst + out.pst) < out.subtotal * 0.05 - 0.06 || (out.pst > 0 && out.pst < out.subtotal * 0.07 - 0.06))
    info.push('Some items are tax-exempt (normal for groceries and prescriptions)');
}
if (out.confidence < 0.7) flags.push(`AI is only ${Math.round(out.confidence * 100)}% sure`);
out.flags = flags;
out.flag_text = flags.length ? '⚠ ' + flags.join(' · ') : '✓ The totals add up';
out.info_text = info.join(' · ');
// Receipt-style card for the review page. n8n strips class attributes from custom HTML,
// so this uses plain tags that the theme CSS styles inside .form-group.html.
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = v => v === null ? '?' : '$' + Number(v).toFixed(2);
const tr = (k, v) => `<tr><td>${k}</td><td>${v}</td></tr>`;
out.review_html = `<h3>${esc(out.vendor)}</h3>`
  + `<p>${esc(out.date)}${out.paid_with ? ' · ' + esc(out.paid_with) : ''}</p>`
  + '<table>' + tr('Subtotal', money(out.subtotal)) + tr('GST', money(out.gst)) + tr('PST', money(out.pst))
  + (out.hst ? tr('HST', money(out.hst)) : '')
  + `<tr><th>Total</th><th>${money(out.total)} ${esc(out.currency)}</th></tr></table>`
  + `<p><small>${esc(out.category)}</small>${names.length ? `<small>Split ${names.length + 1} ways · you pay ${money(out.your_share)}</small>` : ''}</p>`
  + (flags.length ? `<p><em>${esc(out.flag_text)}</em></p>` : `<p><strong>${esc(out.flag_text)}</strong></p>`)
  + (info.length ? `<p><i>${esc(out.info_text)}</i></p>` : '');
return [{ json: out }];

