// One ledger row: the AI's reading plus the human's decision.
const d = $('Parse + check').first().json;
const f = $input.first().json;
const decision = String(f['Decision']).replace(/[\[\]"]/g, '');
const changed = decision === 'Change category' && f['Category'];
const category = changed ? f['Category'] : d.category;
// Receipts a Canadian student should keep for their tax return.
const keep = category === 'Health' ? 'Yes: medical expense tax credit'
  : /tuition/i.test(d.vendor + ' ' + d.notes) ? 'Yes: tuition (match to your T2202)' : '';
return [{ json: {
  'Date': d.date, 'Vendor': d.vendor, 'Subtotal': d.subtotal, 'GST': d.gst, 'PST': d.pst, 'HST': d.hst,
  'Total': d.total, 'Your share': d.your_share, 'Split with': d.split_with, 'Each owes you': d.each_owes,
  'Currency': d.currency, 'Category': category, 'Keep for taxes': keep,
  'AI category': d.category, 'Paid with': d.paid_with, 'Checks': d.flag_text,
  'Note': f['Note'] || '', 'Logged at': new Date().toISOString(),
} }];

// Month-to-date spend vs budget, for the confirmation page.
const BUDGET = 600;
const month = new Date().toISOString().slice(0, 7);
const rows = $input.all().map(i => i.json).filter(r => String(r['Date'] || '').startsWith(month));
const mine = r => Number(r['Your share'] !== '' && r['Your share'] !== undefined ? r['Your share'] : r['Total']) || 0;
const spent = rows.reduce((s, r) => s + mine(r), 0);
const row = $('Build row').first().json;
const cat = rows.filter(r => r['Category'] === row['Category']).reduce((s, r) => s + mine(r), 0);
const owed = {};
for (const r of rows) for (const n of String(r['Split with'] || '').split(',').map(s => s.trim()).filter(Boolean))
  owed[n] = (owed[n] || 0) + (Number(r['Each owes you']) || 0);
const owedText = Object.entries(owed).map(([n, v]) => `${n} $${v.toFixed(2)}`).join(', ');
return [{ json: {
  owed: owedText ? `Owed to you this month: ${owedText}.` : '',
  keep: row['Keep for taxes'] ? `📁 Keep this receipt: ${row['Keep for taxes']}.` : '',
  vendor: row['Vendor'], total: Number(row['Total']).toFixed(2), category: row['Category'],
  spent: spent.toFixed(2), budget: BUDGET, pct: Math.round(spent / BUDGET * 100),
  left: (BUDGET - spent).toFixed(2), cat_spent: cat.toFixed(2), count: rows.length,
  done_html: (() => {
    const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const pct = Math.min(100, Math.round(spent / BUDGET * 100));
    const bar = `<s><mark>${'█'.repeat(Math.round(pct / 5))}</mark>${'█'.repeat(20 - Math.round(pct / 5))}</s>`;
    const r = (k, v) => `<tr><td>${k}</td><td>${v}</td></tr>`;
    return `<b>${esc(row['Vendor'])}</b>$${Number(row['Total']).toFixed(2)} → ${esc(row['Category'])}`
      + `<h4>This month · ${pct}% used</h4>${bar}<table>`
      + r('Spent', `$${spent.toFixed(2)} of $${BUDGET}`) + r('Left', `$${(BUDGET - spent).toFixed(2)}`)
      + r(`${esc(row['Category'])} so far`, `$${cat.toFixed(2)}`)
      + Object.entries(owed).filter(([, v]) => v > 0).map(([n, v]) => r(`${esc(n)} owes you`, `$${v.toFixed(2)}`)).join('')
      + (row['Keep for taxes'] ? r('📁 Keep receipt', esc(row['Keep for taxes'])) : '')
      + '</table>';
  })(),
} }];

